import {View,Text,type ViewProps} from 'react-native';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {ExposureAndWhiteBalance} from '@/components/nyc-tron/ui/components/forge/photo/ExposureAndWhiteBalance';
import {ToneAndPresence} from '@/components/nyc-tron/ui/components/forge/photo/ToneAndPresence';
import {EightBandColorMixer} from '@/components/nyc-tron/ui/components/forge/photo/EightBandColorMixer';
import {LensCorrectionPanel,type LensProfile} from '@/components/nyc-tron/ui/components/forge/photo/LensCorrectionPanel';
import {parsePhotoDevelop,serializePhotoDevelop,validatePhotoDevelop,type PhotoDevelopSettings} from '@/components/nyc-tron/ui/components/forge/photo/photo-adjustments';
export type {PhotoDevelopSettings} from '@/components/nyc-tron/ui/components/forge/photo/photo-adjustments';
export interface RAWDevelopPanelProps extends Omit<ViewProps,'children'> {
 readonly photoId:string;
 readonly revision:string|number;
 readonly value:PhotoDevelopSettings;
 /** Camera/engine-specific defaults, not assumed to be a universal RAW white balance. */
 readonly defaults:PhotoDevelopSettings;
 /** Settings at the beginning of the host's edit session. Original pixels never change. */
 readonly baseline:PhotoDevelopSettings;
 readonly profiles:readonly LensProfile[];
 readonly onCommit:(settings:PhotoDevelopSettings)=>void;
 readonly onCopy:(payload:string,signal:AbortSignal)=>void|Promise<void>;
 readonly onPaste:(signal:AbortSignal)=>string|Promise<string>;
 readonly disabled?:boolean;
 readonly unstyled?:boolean;
}
/** Composes non-destructive RAW settings; does not decode RAW or simulate an image transform. */
export function RAWDevelopPanel({photoId,revision,value,defaults,baseline,profiles,onCommit,onCopy,onPaste,disabled=false,unstyled=false,...props}:RAWDevelopPanelProps){
 if(!photoId.trim()||photoId.length>256||!(typeof revision==='string'||Number.isSafeInteger(revision)))throw new TypeError('Develop panel requires a photo identity and revision');
 validatePhotoDevelop(value);validatePhotoDevelop(defaults);validatePhotoDevelop(baseline);
 const action=useOwnedAction(JSON.stringify([photoId,revision]));
 const locked=disabled||action.pending!==null;
 const serialized=serializePhotoDevelop(value);
 const commit=(next:PhotoDevelopSettings)=>{if(locked)return;validatePhotoDevelop(next);if(serializePhotoDevelop(next)!==serialized)onCommit(next);};
 return <View key={photoId} {...props} style={[{gap:16},props.style]}>
  <Text {...{className:joinClasses(!unstyled&&'text-text')}}>Non-destructive develop settings</Text>
  <View style={{flexDirection:'row',flexWrap:'wrap',gap:8}}>
   <Button title="Reset develop defaults" disabled={locked||serializePhotoDevelop(defaults)===serialized} unstyled={unstyled} onPress={()=>commit(parsePhotoDevelop(serializePhotoDevelop(defaults)))}/>
   <Button title="Revert develop edits" disabled={locked||serializePhotoDevelop(baseline)===serialized} unstyled={unstyled} onPress={()=>commit(parsePhotoDevelop(serializePhotoDevelop(baseline)))}/>
   <Button title="Copy develop settings" disabled={locked} unstyled={unstyled} onPress={()=>{if(!locked)void action.run('copy',signal=>onCopy(serialized,signal));}}/>
   <Button title="Paste develop settings" disabled={locked} unstyled={unstyled} onPress={()=>{if(!locked)void action.run('paste',async signal=>parsePhotoDevelop(await onPaste(signal)),next=>onCommit(next));}}/>
   {action.pending!==null?<Button title="Cancel settings transfer" unstyled={unstyled} onPress={action.cancel}/>:null}
  </View>
  <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
  <ExposureAndWhiteBalance value={value.exposure} onCommit={exposure=>commit({...value,exposure})} disabled={locked} unstyled={unstyled}/>
  <ToneAndPresence value={value.tone} onCommit={tone=>commit({...value,tone})} disabled={locked} unstyled={unstyled}/>
  <LensCorrectionPanel value={value.lens} profiles={profiles} onCommit={lens=>commit({...value,lens})} disabled={locked} unstyled={unstyled}/>
  <EightBandColorMixer value={value.mixer} onCommit={mixer=>commit({...value,mixer})} disabled={locked} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
